### Expected Behavior

Creating a module worker in preload should not block `webContents.send()` delivery to the renderer when launched from VS Code with type: `chrome` and `--remote-debugging-port=9222`. Opening DevTools should not change IPC delivery.

### Actual Behavior

After `did-finish-load`, main-to-renderer IPC messages are queued instead of delivered. Opening DevTools immediately flushes the queue. Reproduces only when the renderer creates a module Worker during startup and the app is launched from the VS Code chrome debugger with `--remote-debugging-port=9222`. Either condition removed avoids the stall.

This worked in Electron 41.5.0.

### Repro

Copy the files below into an empty folder, run `npm install`, then F5 in VS Code with the `.vscode/launch.json` below. Do not open DevTools and wait at least 5 seconds. The spinner stays and the grid never appears. Opening DevTools immediately flushes the queued `show-grid` IPC. Removing the module Worker from `preload.mjs`, or launching via `npm start` or `npm run start-cdp` avoids the stall.

### `package.json`

```json
{
    "name": "vscode-debug-electron",
    "version": "1.0.0",
    "main": "main.js",
    "scripts": {
        "start": "electron .",
        "start-cdp": "electron . --remote-debugging-port=9222 --enable-logging"
    },
    "devDependencies": {
        "electron": "42.0.1"
    }
}
```

### `main.js`

```js
const { app, BrowserWindow, Menu } = require('electron');
const fs = require('fs');
const path = require('path');

const LOG_PATH = '/tmp/electron-worker-startup-repro-main.log';
const log = (message) => fs.appendFileSync(LOG_PATH, `${Date.now()} ${message}\n`);

fs.writeFileSync(LOG_PATH, '');

let mainWindow = null;
let showGridTimer = null;

function createWindow() {
    mainWindow = new BrowserWindow({
        width: 720,
        height: 520,
        webPreferences: {
            preload: path.join(__dirname, 'preload.mjs'),
            contextIsolation: true,
            sandbox: false
        }
    });

    mainWindow.webContents.once('did-finish-load', () => {
        log('did-finish-load');
        showGridTimer = setTimeout(() => {
            if (!mainWindow || mainWindow.isDestroyed() || mainWindow.webContents.isDestroyed()) {
                return;
            }
            const sentAt = Date.now();
            log(`send show-grid sentAt=${sentAt}`);
            mainWindow.webContents.send('show-grid', { sentAt });
        }, 1000);
    });

    mainWindow.on('closed', () => {
        if (showGridTimer) {
            clearTimeout(showGridTimer);
            showGridTimer = null;
        }
        mainWindow = null;
    });

    mainWindow.loadFile(path.join(__dirname, 'index.html'));

    Menu.setApplicationMenu(Menu.buildFromTemplate([
        { role: 'appMenu' },
        { label: 'View', submenu: [{ role: 'toggleDevTools' }, { role: 'reload' }] }
    ]));
}

app.whenReady().then(createWindow);
app.on('window-all-closed', () => app.quit());
```

### `preload.mjs`

```js
import { ipcRenderer } from 'electron';
import fs from 'fs';

const LOG_PATH = '/tmp/electron-worker-startup-repro-renderer.log';
const log = (message) => fs.appendFileSync(LOG_PATH, `${Date.now()} ${message}\n`);

fs.writeFileSync(LOG_PATH, '');
log('preload start');

ipcRenderer.on('show-grid', (_event, { sentAt }) => {
    const receivedAt = Date.now();
    const delay = receivedAt - sentAt;
    log(`received show-grid sentAt=${sentAt} receivedAt=${receivedAt} delay=${delay}ms`);
    window.document.body.classList.remove('spinner');
    window.document.body.classList.add('ready');
    window.document.getElementById('delay').textContent = `${delay} ms`;
});

window.addEventListener('load', () => {
    log('window load');
    const worker = new Worker('./worker.js', { type: 'module' });
    worker.addEventListener('message', (event) => {
        log(`worker message ${JSON.stringify(event.data)}`);
    });
    window.__workerProbe = worker;
    log('module worker created');
});
```

